/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_QUOTE_RATING
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_QUOTE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_QUOTE_HK
   hashdiff    : SAT_QUOTE_RATING_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_QUOTE|' || (HUB_QUOTE_BK__QUOTATION_NO))) as HUB_QUOTE_HK
        , RATE_YN as RATE_BASED_QUOTATION_INDICATOR
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(QUOTATION_NO),'')) is not null
),

resolved as (
    select
        HUB_QUOTE_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then RATE_BASED_QUOTATION_INDICATOR end) as RATE_BASED_QUOTATION_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_QUOTE_HK
),

hashed as (
    select
        *,
        case when RATE_BASED_QUOTATION_INDICATOR is not null
                     then md5(upper(coalesce(cast(RATE_BASED_QUOTATION_INDICATOR as varchar), '')))
                end as SAT_QUOTE_RATING_HASHDIFF
    from resolved
)

select * from hashed
where HUB_QUOTE_HK is not null
  and SAT_QUOTE_RATING_HASHDIFF is not null
